/*!
 * @brief Type representing event status flags (64-bit).
 * Used with EVENT_CTRL_GetEventStatus and EVENT_CTRL_ClearEventStatus.
 * See @ref _event_ctrl_evtstatus for bit definitions.
 */
typedef uint64_t event_ctrl_event_status_t;

