/*!
 * @brief DMA instance selection.
 * Enumeration for selecting between available SDMA instances.
 */
typedef enum _dma_instance
{
    kSDMA0 = 0U, /*!< SDMA0 instance */
    kSDMA1 = 1U, /*!< SDMA1 instance */
    kSDMA_COUNT = 2U /*!< Number of DMA instances */
} dma_instance_t;

/*!
 * @brief CTIMER instance selection.
 * Enumeration for selecting between available CTIMER instances (0-4).
 */
typedef enum _ctimer_instance
{
    kCTIMER0 = 0U, /*!< CTIMER0 instance */
    kCTIMER1 = 1U, /*!< CTIMER1 instance */
    kCTIMER2 = 2U, /*!< CTIMER2 instance */
    kCTIMER3 = 3U, /*!< CTIMER3 instance */
    kCTIMER4 = 4U, /*!< CTIMER4 instance */
    kCTIMER_COUNT = 5U /*!< Number of CTIMER instances */
} ctimer_instance_t;
/*!
 * @brief Get interrupt status.
 * @param base EVENT_CTRL base
 * @return Interrupt status flags. See @ref event_ctrl_interrupt_status_t for bit definitions.
 */
event_ctrl_interrupt_t EVENT_CTRL_GetInterruptStatus(const EVENT_CTRL_Type *base);

/*!
 * @brief Enable interrupts.
 * @param base EVENT_CTRL base
 * @param mask Interrupt mask. See @ref event_ctrl_interrupt_status_t for bit definitions.
 */
void EVENT_CTRL_EnableInterrupts(EVENT_CTRL_Type *base, event_ctrl_interrupt_t mask);

/*!
 * @brief Disable interrupts.
 * @param base EVENT_CTRL base
 * @param mask Interrupt mask. See @ref event_ctrl_interrupt_status_t for bit definitions.
 */
void EVENT_CTRL_DisableInterrupts(EVENT_CTRL_Type *base, event_ctrl_interrupt_t mask);

/*!
 * @brief Clear interrupt status.
 * @param base EVENT_CTRL base
 * @param mask Interrupt status mask to clear. See @ref event_ctrl_interrupt_status_t for bit definitions.
 */
void EVENT_CTRL_ClearInterruptStatus(EVENT_CTRL_Type *base, event_ctrl_interrupt_t mask);

/*!
 * @brief Get event status.
 * @param base EVENT_CTRL base
 * @return Event status flags. See @ref event_ctrl_event_status_t for bit definitions.
 */
event_ctrl_event_status_t EVENT_CTRL_GetEventStatus(const EVENT_CTRL_Type *base);

/*!
 * @brief Clear event status.
 * @param base EVENT_CTRL base
 * @param mask Event status mask to clear. See @ref event_ctrl_event_status_t for bit definitions.
 */
void EVENT_CTRL_ClearEventStatus(EVENT_CTRL_Type *base, event_ctrl_event_status_t mask);

/*!
 * @brief Generate programmable output events.
 *
 * Use the @ref _event_ctrl_output_event enum values to construct the mask parameter.
 *
 * The function completes all earlier memory writes of the calling CPU (data synchronization
 * barrier) before it generates the events, so data the CPU wrote to shared memory is visible
 * to the receiving core when the event arrives. It does not cover data written by a DMA, which
 * is ordered by the DMA completion, nor data held in a data cache, which the caller must clean
 * for the shared range first.
 *
 * @param base  EVENT_CTRL base
 * @param mask  Bitwise OR of @ref _event_ctrl_output_event to generate.
 */
void EVENT_CTRL_GenerateOutputEvent(EVENT_CTRL_Type *base, event_ctrl_output_event_t mask);

/*!
 * @brief Get peripheral event DMA instance selection.
 * @param base EVENT_CTRL base
 * @return Peripheral event DMA instance selection value.
 */
uint32_t EVENT_CTRL_GetPeriphEvtDmaInstSel(const EVENT_CTRL_Type *base);

/*!
 * @brief Set peripheral event DMA instance selection.
 * @param base EVENT_CTRL base
 * @param mask Peripheral event DMA instance selection value to set.
 */
void EVENT_CTRL_SetPeriphEvtDmaInstSel(EVENT_CTRL_Type *base, uint32_t mask);

/*!
 * @brief Forward DMA complete event to NSS.
 * @param base EVENT_CTRL base
 * @param dmaChannel DMA channel number [0:23] @ref sdma0_request_t
 * 
 * There are 24 DMA complete events coming from the DMA controller with only 4 output events available
 * to the NSS. This function allows to forward one of the DMA complete events to NSS.
 * Hardware Event Routing:
 * DMA channels 0-5: output_event[0]
 * DMA channels 6-11: output_event[1]
 * DMA channels 12-17: output_event[2]
 * DMA channels 18-23: output_event[3]
 * 
 * @return Status of the operation.
 */
status_t EVENT_CTRL_EnableDMACompleteEventToNSS(EVENT_CTRL_Type *base, uint32_t dmaChannel);

/*!
 * @brief Forward DMA complete event to ADSS.
 * @param base EVENT_CTRL base
 * @param dmaChannel DMA channel number [0:23] @ref sdma0_request_t
 * 
 *
 * There are 24 DMA complete events coming from the DMA controller with only 4 output events available
 * to the NSS. This function allows to forward one of the DMA complete events to ADSS.
 * Hardware Event Routing:
 * DMA channels 0-5: output_event[0]
 * DMA channels 6-11: output_event[1]
 * DMA channels 12-17: output_event[2]
 * DMA channels 18-23: output_event[3]
 * 
 * @return Status of the operation.
 */
status_t EVENT_CTRL_EnableDMACompleteEventToADSS(EVENT_CTRL_Type *base, uint32_t dmaChannel);

/*!
 * @brief Forward CTIMER match event to NSS.
 * @param base EVENT_CTRL base
 * @param ctimer_instance CTIMER instance number [0:4]
 * @param match_index Match index [0:3]
 * @param mux_output Mux output selection [0:3]
 * 
 * Each one of the 5 CT timers has 4 match events.
 * This function allows to forward one of the CTIMER match event to NSS.
 * There are 4 output events (i.e. mux outputs) available for the NSS subsystem.
 * 
 * @return Status of the operation.
 */
